2741: function enable_sbd(dialog) {
2742:   ajax_wrapper({
2743:     type: 'POST',
2744:     url: get_cluster_remote_url() + "remote_enable_sbd",
2745:     data: dialog.find("#enable_sbd_form").serialize(),
2746:     timeout: pcs_timeout,
2747:     success: function() {
2748:       dialog.parent().find("#enable_sbd_btn").button(
2749:         "option", "disabled", false
2750:       );
2751:       dialog.dialog("close");
2752:       alert(
2753:         'SBD enabled! You have to restart cluster in order to apply changes.'
2754:       );
2755:       Pcs.update();
2756:     },
2757:     error: function (xhr, status, error) {
2758:       dialog.parent().find("#enable_sbd_btn").button(
2759:         "option", "disabled", false
2760:       );
2761:       xhr.responseText = xhr.responseText.replace(
2762:         "--skip-offline", "option 'ignore offline nodes'"
2763:       );
2764:       alert(
2765:         ajax_simple_error(xhr, status, error)
2766:       );
2767:     }
2768:   });
2769: }
